"""Verify final exports and write audit report; readiness receipt follows visual sheet inspection."""
from pathlib import Path
import json,hashlib,shutil
from PIL import Image,ImageDraw,ImageFont
OUT=Path('/home/coding-agent/workspace/output/instaplaque-serp-images-20261110');PHOTOS=OUT/'photos';QA=OUT/'qa'
m=json.loads((OUT/'measurements.json').read_text());kept=[k for k,d in m.items() if d['kept']]
files=[]
for k in kept:
 assert m[k]['ratio_error_percent']<2
 assert m[k]['og_min_margin_frame_percent']>=6
 for name,size in [('master',tuple(m[k]['native'])),('1x1',(1200,1200)),('4x3',(1200,900)),('16x9',(1200,675)),('og',(1200,630))]:
  for ext in (['jpg'] if name=='master' else ['jpg','webp']):
   p=PHOTOS/f'{k}-{name}.{ext}';im=Image.open(p);assert im.size==size
   files.append(dict(file=str(p.relative_to(OUT)),size=im.size,bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()))
assert len(files)==len(kept)*9
(OUT/'manifest.json').write_text(json.dumps(files,indent=2))
f=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',22)
og=Image.new('RGB',(640,len(kept)*365),'white');thumbs=Image.new('RGB',(len(kept)*160,170),'white')
for i,k in enumerate(kept):
 ImageDraw.Draw(og).text((20,i*365+8),k+' · 1200×630 centre crop',font=f,fill='black')
 og.paste(Image.open(PHOTOS/f'{k}-og.jpg').resize((600,315)),(20,i*365+42))
 ImageDraw.Draw(thumbs).text((i*160+8,8),k,font=f,fill='black');thumbs.paste(Image.open(PHOTOS/f'{k}-1x1.jpg').resize((120,120)),(i*160+8,40))
og.save(QA/'OG-CROPS.jpg',quality=93);thumbs.save(QA/'THUMBNAILS-120px.jpg',quality=95)
lines=['# SERP photo review — 10 November 2026','','Photos only. **Nothing deployed or changed in public/site code, production, Merchant Center, Google Ads or Search Console.**','','## Selection','','Kept: '+', '.join(kept)+'.','','Rejected: G2.v2 — raised/button-like caps, and plate width 39.47% rather than the required 40–50%. Its 0.9841:1 ratio passes the 2% tolerance, but the fixing and framing do not.','','| Version | Verdict | Measured width:height | Error from true | Frame width | OG minimum clearance¹ | Text |','|---|---|---:|---:|---:|---:|---|']
for k,d in m.items():lines.append(f"| {k} | {'KEEP' if d['kept'] else 'REJECT'} | {d['ratio']:.5f}:1 | {d['ratio_error_percent']:.3f}% | {d['width_percent']:.2f}% | {d['og_min_margin_frame_percent']:.2f}% | PASS |")
lines += ['', '¹Clearance is measured conservatively as a percentage of the entire square master, between the whole plate and each edge of the centred 1200×630 band. All kept images exceed 6%; 16:9 is taller and therefore also passes.', '', 'Measurements use native 1254×1254 pixels, metal-face segmentation, and visually verified green-outline evidence in `qa/*-measured.jpg`. Expected uncertainty is about one pixel at a metal/antialiased edge. G2.v1 measures 39.952% width, which is 40.0% at the precision of the framing target (less than one pixel below exactly 40%). Its height is 40.03%. The circle is within 0.20% of 1:1.', '', 'All retained rectangles are level: measured average top/bottom slopes are S.v1 +0.086°, S.v2 +0.020°, G1.v1 −0.032°, G1.v2 +0.037°. The circle fixing centres and wording are visually level. Coded guide overlays retain the bench rail alignment and plausible surface scale.', '', '## Exact text: every line zoom-checked', '', '**S.v1 and S.v2 — PASS**', '', '```text', 'In loving memory of', 'NORMA BRADSHAW', '1922 – 2009', 'Sit and rest awhile', '```', '', 'Exact product designer drawing layout; 150×65 proportions; single thin black border; four low cross-head screws. Centred on and aligned with the bench’s upper rail. Natural green/flower bokeh. Black paint-filled lettering, no extra or warped letters.', '', '**G1.v1 and G1.v2 — PASS**', '', '```text', 'In loving memory of', 'SUSAN MARSH', '1951 – 2022', '```', '', 'Exact garden-hero artwork; A5 210×148 proportions; inward-scalloped border around four thin smooth flat caps. Old red brick and climbing roses: blooms are visible beside the plaque in both square and OG crops. Black paint-filled lettering, no extra or warped letters.', '', '**G2.v1 and G2.v2 — text PASS; only v1 kept**', '', '```text', 'In loving memory of', 'MAY', 'ATHERTON', '1924 – 2019', '```', '', 'Round-two circle artwork, double thin circular border, two smooth brass caps. V1 has thin cap faces and a near-exact true circle. V2 is rejected as above. Black paint-filled lettering, no extra or warped letters. All date separators visually checked as en dashes.', '', '## Files and verification', '', f'- {len(kept)} full-native JPEG masters, {len(kept)*8} derivative crops. All masters preserve the generated pixels; no plaque stretching, compositing, typography patching or geometry correction.', '- Runner requested 2048×2048; the subscription route actually returned 1254×1254. Those native files are the masters. Each 1200px crop is downsampled, not upscaled.', '- JPEG crops q90, WebP q85; 1x1 1200×1200, 4x3 1200×900, 16x9 1200×675, OG 1200×630.', '- Every master and crop uses the repository `publish-codex-photos.py` tagging function. `iptc-verification.json` independently confirms the exact `trainedAlgorithmicMedia` URI on every file.', '- `manifest.json`: dimensions, sizes, SHA-256 hashes. `measurements.json`: inspected selection and native plate coordinates.', '- `SERP-SHEET.jpg`: 800px wide; owner screenshots as Now, then exact screenshot copy/prices with each retained rounded thumbnail and a 500px photo below. These are review mock-ups, not live Google results.', '- `qa/OG-CROPS.jpg` and `qa/THUMBNAILS-120px.jpg` support crop/thumbnail inspection.', '', '## Generation and scope', '', 'Six completed generations, two per job, through the existing unchanged `run_batch.py` route on `openai/gpt-image-2` / the ChatGPT subscription, one at a time inside `cody-job`. One earlier CLI attempt was interrupted before output when a source-artwork crop issue was caught; corrected guide was rechecked before the complete six-image run. Conservatively seven attempts total, below the eight-call cap. No paid image API or fallback, no rate-limit error, no additional retry.', '', 'Resource checks before heavy work: more than 7 GiB available RAM and 51 GiB free disk. Source scripts exist only on `codex/instaplaque-serp-images-20261110`; image binaries remain in the designated output directory. Owner choice and any later release are separate.', '']
(OUT/'REVIEW.md').write_text('\n'.join(lines));shutil.copy2(OUT/'REVIEW.md',PHOTOS/'REVIEW.md')
print(f'Verified {len(files)} image exports; wrote review, hashes, OG and 120px QA sheets.')
